// DATOS SIMULADOS: no provienen del PLC.
// Ciclo de 40 s: 30 s en marcha, 10 s detenido. Un producto nuevo cada 10 s.
const POS_ENTRADA = 0.19;
const POS_SALIDA  = 0.81;
const AVANCE      = 1 / 8;    // el producto cruza la banda en 8 s

let s = context.get("sim") || { tick: 0, productos: [], contador: 0 };
s.tick++;

const motor = (s.tick % 40) < 30;

if (motor) {
    if (s.tick % 10 === 5) s.productos.push(0);
    const siguientes = [];
    s.productos.forEach((p) => {
        const nueva = p + AVANCE;
        if (p < POS_SALIDA && nueva >= POS_SALIDA) s.contador++;
        if (nueva <= 1) siguientes.push(nueva);
    });
    s.productos = siguientes;
}
context.set("sim", s);

const cerca = (pos) => s.productos.some((p) => Math.abs(p - pos) < 0.07);

msg.payload = {
    origen: "SIMULACION",
    timestamp: new Date().toISOString(),
    motor: motor,
    sensorEntrada: cerca(POS_ENTRADA),
    sensorSalida: cerca(POS_SALIDA),
    productos: s.contador,
    modo: "AUTOMÁTICO",
    alarmas: motor ? [] : [{ codigo: "SIM-01", mensaje: "Motor detenido (alarma simulada)" }]
};
return msg;

// Convierte las lecturas OPC UA al formato que espera la interfaz.
// Toda la configuración (origen y variables) viene del nodo de CONFIGURACIÓN.
const CONFIG = flow.get("config");
if (!CONFIG) return null;

// Por si el topic llega con el sufijo ";datatype=...", se lo quitamos
const topicLimpio = String(msg.topic).split(";datatype=")[0];

let campo = null;
for (const [nombre, v] of Object.entries(CONFIG.variables)) {
    if (v.nodeId === topicLimpio) campo = nombre;
}
if (!campo) return null;                 // lectura desconocida: se ignora

let valores = context.get("valores") || {};
valores[campo] = msg.payload;
context.set("valores", valores);

// No se envía nada hasta tener todas las variables configuradas
const completo = Object.keys(CONFIG.variables).every((n) => valores[n] !== undefined);
if (!completo) return null;

// Solo viajan las variables configuradas. "modo" y "alarmas" no se envían
// mientras no exista una señal real que las respalde.
const payload = { origen: CONFIG.origen, timestamp: new Date().toISOString() };
Object.assign(payload, valores);
return { payload: payload };

// ===== CONFIGURACIÓN DE LA FUENTE DE DATOS: ÚNICO LUGAR A EDITAR =====
// "origen" debe ser "PLC" SOLO cuando los datos vengan del PLC real.
const CONFIG = {
    origen: "SIMULACION",
    variables: {
        // nombre que usa la interfaz : NodeId en el servidor y tipo de dato
        motor:         { nodeId: "ns=1;s=motor",         tipo: "Boolean" },
        sensorEntrada: { nodeId: "ns=1;s=sensorEntrada", tipo: "Boolean" },
        sensorSalida:  { nodeId: "ns=1;s=sensorSalida",  tipo: "Boolean" },
        productos:     { nodeId: "ns=1;s=productos",     tipo: "UInt32"  },
        arrancar:      { nodeId: "ns=1;s=arrancar",      tipo: "Boolean" } // orden de arranque (escritura)
        // Variable que NO existe en el PLC: borra su línea y la interfaz
        // mostrará "No disponible". No inventes NodeId.
    }
};

flow.set("config", CONFIG);   // "Armar datos" lee la configuración de aquí

// Una orden de lectura por variable.
const mensajes = Object.values(CONFIG.variables).map((v) => ({
    topic: v.nodeId + ";datatype=" + v.tipo
}));
return [mensajes];

// La interfaz envía { arrancar: true|false } por el WebSocket.
// Cualquier otro mensaje se ignora: solo se acepta esta orden.
let orden = msg.payload;
if (typeof orden === "string") {
    try { orden = JSON.parse(orden); } catch (e) { return null; }
}
if (!orden || typeof orden.arrancar !== "boolean") return null;

msg.topic = "ns=1;s=arrancar;datatype=Boolean";
msg.payload = orden.arrancar;
return msg;
